package org.jlinalg.protein;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import org.junit.jupiter.api.Test;

class ProteinStructureTest {
    private static String atom(int serial,String name,String chain,int residue,String insertion,String alt,double score){char[] line=" ".repeat(80).toCharArray();put(line,0,"ATOM  ");put(line,6,String.format(Locale.ROOT,"%5d",serial));put(line,12," CA ");put(line,16,alt);put(line,17,name);put(line,21,chain);put(line,22,String.format(Locale.ROOT,"%4d",residue));put(line,26,insertion);put(line,30,String.format(Locale.ROOT,"%8.3f",serial*1.5));put(line,38,String.format(Locale.ROOT,"%8.3f",serial*.5));put(line,46,String.format(Locale.ROOT,"%8.3f",-serial*.1));put(line,54,"  1.00");put(line,60,String.format(Locale.ROOT,"%6.2f",score));put(line,76," C");return new String(line)+"\n";}
    private static void put(char[] line,int at,String value){for(int i=0;i<value.length();i++)line[at+i]=value.charAt(i);}
    @Test void pdbConfidenceBoundariesAndAuthorNumberingPreserveExactSequence(){String[] amino={"ALA","CYS","ASP","GLU","PHE","GLY","HIS","ILE"};double[] confidence={0,49,50,69,70,89,90,100};var source=new StringBuilder();for(int i=0;i<amino.length;i++)source.append(atom(i+1,amino[i],"A",101+i,"","",confidence[i]));var model=ProteinStructure.parse(source.toString(),"pdb",1,true,20);var result=ProteinStructure.assess(model,"A","ACDEFGHI",1,Map.of(),"");assertEquals("exact_complete_coordinate_sequence",result.sequenceMatch());assertEquals(1,result.coverage());assertEquals(101,result.residues().get(0).residue().authorNumber());assertEquals(1,result.residues().get(0).sequencePosition());assertEquals(64.625,result.meanPlddt(),1e-13);assertEquals(.25,result.fractionVeryLow());assertEquals(.25,result.fractionLow());assertEquals(.25,result.fractionConfident());assertEquals(.25,result.fractionVeryHigh());}
    @Test void experimentalBFactorsAreNotSilentlyInterpretedAsPlddt(){String source=atom(1,"ALA","A",1,"","",170);var model=ProteinStructure.parse(source,"pdb",1,false,10);assertTrue(Double.isNaN(ProteinStructure.assess(model,"A","A",1,Map.of(),"").meanPlddt()));assertThrows(IllegalArgumentException.class,()->ProteinStructure.parse(source,"pdb",1,true,10));}
    @Test void cifLoopsQuotesMultilineMetadataAndPolymerSequenceAreParsed(){String source="data_synthetic\n_note.text\n;arbitrary metadata\nwith loop_ and _atom_site tokens inside a quoted text value\n;\nloop_\n_entity_poly_seq.entity_id\n_entity_poly_seq.num\n_entity_poly_seq.mon_id\n1 1 ALA\n1 2 CYS\n1 3 ASP\n#\nloop_\n_struct_asym.id\n_struct_asym.entity_id\n'A' 1\n#\nloop_\n_atom_site.group_PDB\n_atom_site.label_atom_id\n_atom_site.label_comp_id\n_atom_site.label_asym_id\n_atom_site.label_entity_id\n_atom_site.label_seq_id\n_atom_site.auth_seq_id\n_atom_site.Cartn_z\n_atom_site.Cartn_x\n_atom_site.Cartn_y\n_atom_site.B_iso_or_equiv\n_atom_site.pdbx_PDB_model_num\nATOM 'CA' ALA A 1 1 101 3.0 1.0 2.0 95 2\nATOM \"CA\" ASP A 1 3 103 4.0 2.0 3.0 40 2\n#\n";var model=ProteinStructure.parse(source,"cif",2,true,10);assertEquals("ACD",model.polymerSequences().get("A"));assertEquals(List.of("A"),model.chains());var result=ProteinStructure.assess(model,"A","ACD",1,Map.of(),"");assertEquals("declared_full_polymer_with_partial_coordinates",result.sequenceMatch());assertEquals(2.0/3,result.coverage(),1e-14);assertEquals(3,result.residues().get(1).sequencePosition());assertEquals(67.5,result.meanPlddt());assertThrows(IllegalArgumentException.class,()->ProteinStructure.parse(source,"cif",1,true,10));}
    @Test void partialModelsRequireIdentityAndAnUnambiguousResidueMap(){String source=atom(1,"ALA","A",100,"A","",90)+atom(2,"ASP","A",300,"","",80);var model=ProteinStructure.parse(source,"pdb",1,true,10);assertThrows(IllegalArgumentException.class,()->ProteinStructure.assess(model,"A","ACD",1,Map.of(),""));var mapped=ProteinStructure.assess(model,"A","ACD",1,Map.of("A:100:A",1,"A:300:",3),"");assertEquals(2.0/3,mapped.coverage(),1e-14);assertThrows(IllegalArgumentException.class,()->ProteinStructure.assess(model,"A","ACE",1,Map.of("A:100:A",1,"A:300:",3),""));assertThrows(IllegalArgumentException.class,()->ProteinStructure.assess(model,"A","ACD",1,Map.of("A:100:A",1,"A:300:",1),""));}
    @Test void modelFragmentUsesDeclaredSequenceStartAndNeverClaimsWholeIsoformEquivalence(){var model=ProteinStructure.parse(atom(1,"CYS","A",101,"","",90)+atom(2,"ASP","A",102,"","",80),"pdb",1,true,10);var fragment=ProteinStructure.assess(model,"A","ACDE",2,Map.of(),"CD");assertEquals(List.of(2,3),fragment.residues().stream().map(ProteinStructure.Mapped::sequencePosition).toList());assertEquals(.5,fragment.coverage());assertEquals("coordinate_identity_verified_partial_sequence_context",fragment.sequenceMatch());assertThrows(IllegalArgumentException.class,()->ProteinStructure.assess(model,"A","ACDE",1,Map.of(),"CD"));}
    @Test void paeDirectionsStayAsymmetricAndRegionsAreExplicit(){double[][] matrix={{0,2},{10,0}};var result=ProteinStructure.pae(matrix,List.of(new ProteinStructure.Region("A",1,1),new ProteinStructure.Region("B",2,2)),4);assertEquals(2,result.stream().filter(r->r.alignedRegion().equals("A")&&r.evaluatedRegion().equals("B")).findFirst().orElseThrow().mean());assertEquals(10,result.stream().filter(r->r.alignedRegion().equals("B")&&r.evaluatedRegion().equals("A")).findFirst().orElseThrow().mean());assertThrows(IllegalArgumentException.class,()->ProteinStructure.pae(matrix,List.of(new ProteinStructure.Region("out",1,3)),4));assertThrows(IllegalArgumentException.class,()->ProteinStructure.pae(new double[][]{{0,-1},{1,0}},List.of(),4));assertThrows(IllegalArgumentException.class,()->ProteinStructure.pae(matrix,List.of(),3));}
    @Test void chainsAlternateLocationsAndPeptideAmbiguityAreNotChosenByConfidence(){String source=atom(1,"ALA","A",1,"","A",99)+atom(2,"ALA","A",1,"","",10)+atom(3,"ALA","A",1,"","B",100)+atom(4,"ALA","B",1,"","",90);var model=ProteinStructure.parse(source,"pdb",1,true,10);assertThrows(IllegalArgumentException.class,()->ProteinStructure.assess(model,"","A",1,Map.of(),""));assertEquals(10,ProteinStructure.assess(model,"A","A",1,Map.of(),"").meanPlddt());assertEquals(List.of(1,3),ProteinStructure.peptidePositions("ACAC","AC"));assertEquals(List.of(),ProteinStructure.peptidePositions("ACAC","VV"));assertThrows(IllegalArgumentException.class,()->ProteinStructure.parse(atom(1,"ALA","A",1,"","",90)+atom(2,"ALA","A",1,"","",80),"pdb",1,true,10));}
    @Test void fastaIdentityStopsAndUnknownResiduesRemainExplicit(){var parsed=ProteinStructure.fasta(">isoform-2 source version\na c\nDU\n",2,10);assertEquals("ACDU",parsed.get("isoform-2"));assertThrows(IllegalArgumentException.class,()->ProteinStructure.fasta(">same\nAC\n>same\nAD\n",3,10));assertThrows(IllegalArgumentException.class,()->ProteinStructure.sequence("ACD*"));assertThrows(IllegalArgumentException.class,()->ProteinStructure.fasta(">too-long\nACDE\n",2,3));var x=ProteinStructure.parse(atom(1,"UNK","A",1,"","",50),"pdb",1,true,10);assertEquals(1,ProteinStructure.assess(x,"A","X",1,Map.of(),"").ambiguousAminoAcids());}
}
